/* From Uiverse.io by ahmed150up - Tags: card */
.__UIV_SCOPE__ .voice-chat-card {
  width: 300px;
  margin: 20px auto;
  border: 1px solid #ccc;
  border-radius: 10px;
  box-shadow: 2px 2px 10px #ccc;
  padding: 10px;
  background-color: #e8e8e8;
}

.__UIV_SCOPE__ .voice-chat-card-header {
  display: flex;
  align-items: center;
  margin-bottom: 10px;
}

.__UIV_SCOPE__ .avatar {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  margin-right: 10px;
  color: black;
  background-color: #333;
}

.__UIV_SCOPE__ .username {
  margin: 0;
  font-size: 18px;
  color: black;
}

.__UIV_SCOPE__ .status {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: green;
  margin-left: 10px;
}

.__UIV_SCOPE__ .voice-chat-card-body {
  padding: 10px;
}

.__UIV_SCOPE__ .status-text {
  font-size: 14px;
  margin-bottom: 10px;
}

.__UIV_SCOPE__ .audio-container {
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ audio {
  width: 100%;
}
